import React, { HTMLAttributes } from 'react';

import ClockHistory from '@pohodnik/icons/svg/DateTime/ClockHistory';
import LightningCharge from '@pohodnik/icons/svg/Misc/LightningCharge';
import Trash2 from '@pohodnik/icons/svg/RealWorld/Trash2';
import clsx from 'clsx';

interface IRecipeCookingInfoProps extends HTMLAttributes<HTMLSpanElement> {
  cooking_time: number | null;
  water_count: number | null;
  gas_count: number | null;
  members_count: number;
}

const RecipeCookingInfo: React.FC<IRecipeCookingInfoProps> = ({
  members_count,
  cooking_time,
  water_count,
  gas_count,
  ...rest
}) => {
  return (
    <small
      {...rest}
      className={clsx('d-flex align-items-center', rest.className)}
      style={{ gap: 6 }}
    >
      {!!cooking_time && (
        <small title="Время приготовления в минутах">
          <ClockHistory />
          &thinsp;{cooking_time}
        </small>
      )}

      {!!water_count && (
        <small title="Необходимое количество воды">
          <Trash2 />
          &thinsp;{water_count * members_count}
        </small>
      )}
      {!!gas_count && (
        <small title="Необходимое количество газа">
          <LightningCharge />
          &thinsp;{gas_count * members_count}
        </small>
      )}
    </small>
  );
};

export default RecipeCookingInfo;
